// Etapa 1 — GUION (Claude): toma el siguiente tema pendiente de Sheets,
// genera el guion + cortos y crea la fila de produccion. Emite VIDEO_ID.
const { execSync } = require('child_process');
const SCRIPT = '/Users/cex/Documents/Workspace/tools/agente_videos/run_pipeline.sh';
const opts = { timeout: 1800000, maxBuffer: 67108864, encoding: 'utf8' };
let out;
try {
  out = execSync(`${SCRIPT} --solo guion`, opts);
} catch (e) {
  const log = ((e.stdout || '') + (e.stderr || '')).slice(-4000);
  throw new Error('Fallo la etapa GUION.\n' + log);
}
const m = out.match(/VIDEO_ID=(\d+)/);
if (!m) throw new Error('No se pudo resolver VIDEO_ID (puede que no haya temas pendientes).\n' + out.slice(-3000));
return [{ json: { video_id: Number(m[1]), etapa: 'guion', ok: true, log: out.slice(-3000) } }];

